const b = $json.body || {};
const src = (b.source ?? '').toString().trim();
const phone = (b.phone ?? '').toString().trim();
const email = (b.email ?? '').toString().trim();
const errors = [];
if (!src) errors.push('missing source');
const hasPhone = phone !== '';
const hasEmail = email !== '';
if (!hasPhone && !hasEmail) errors.push('missing both phone and email');
const e164 = /^\+[1-9]\d{7,14}$/;
if (hasPhone && !e164.test(phone)) errors.push('phone not valid E.164');
const _valid = errors.length === 0;
return [{ json: {
  source: src || null,
  source_id: (b.source_id ?? null),
  first_name: (b.first_name ?? null),
  last_name: (b.last_name ?? null),
  phone: phone || null,
  email: email || null,
  property_interest: (b.property_interest ?? null),
  area_of_interest: (b.area_of_interest ?? null),
  message: (b.message ?? null),
  _valid,
  _reason: errors.join('; ')
} }];

const j = $json;
const phone_norm = (j.phone ?? '').toString().replace(/\D/g, '');
const email_norm = (j.email ?? '').toString().toLowerCase().trim();
const source = (j.source ?? '').toString();
const prefixes = [['971','AE'],['966','SA'],['974','QA'],['965','KW'],['973','BH'],['968','OM'],['212','MA'],['961','LB'],['962','JO'],['20','EG']];
let country_code = null;
for (const [p, iso] of prefixes) { if (phone_norm.startsWith(p)) { country_code = iso; break; } }
const dedup_source_string = phone_norm + '|' + email_norm + '|' + source;
return [{ json: { ...j, phone_norm, email_norm, country_code, dedup_source_string } }];

const lead = $('Compute Dedup Key').item.json;
const msg = (lead.message || '').toString();
const system = [
 'You are a language detector for a real-estate lead-response system serving the MENA region.',
 'Determine the DOMINANT language of the message. Allowed values:',
 '- "ar" Arabic (any dialect, Arabic script OR Latin/Arabizi like "3ayez", "keefak").',
 '- "en" English',
 '- "fr" French',
 '- "mixed" two or more used roughly equally, no single dominant one.',
 'Rules: place/project names do NOT count toward a language. Arabizi counts as "ar".',
 'If one language carries the meaning and the other is only a name/loanword, pick the dominant one, not "mixed".',
 'Output STRICT JSON only, no prose/markdown/fences. Shape: {"language":"ar|en|fr|mixed","confidence":0.0-1.0}'
].join('\n');
const body = { model: 'claude-haiku-4-5-20251001', max_tokens: 60, system, messages: [{ role: 'user', content: 'Message:\n"""\n' + msg + '\n"""' }] };
return [{ json: { anthropic_body: body } }];

const lead = $('Compute Dedup Key').item.json;
const system = [
 'You classify inbound real-estate leads for MENA agencies. Assign ONE intent level.',
 '- "high" ready-to-transact: cash/pre-approved, specific building/unit, near-term timeline, request to view.',
 '- "medium" genuine but exploratory: named area/type without firm budget/timeline.',
 '- "low" casual browsing: vague, no area, no timeline.',
 '- "junk" spam, fake identity (nonsense name/random digits), tests, bots, unrelated.',
 'Rules: judge substance not politeness. Fake name + no real interest => junk.',
 'Currency is never assumed; a bare number is not a strong budget signal.',
 'Consider Arabic (incl Arabizi), English, French equally.',
 'Output STRICT JSON only. Shape: {"intent":"high|medium|low|junk","reason":"<=12 words"}'
].join('\n');
const user = [
 'Lead data:',
 '- source: ' + (lead.source || ''),
 '- name: ' + ((lead.first_name || '') + ' ' + (lead.last_name || '')).trim(),
 '- property_interest: ' + (lead.property_interest || ''),
 '- area: ' + (lead.area_of_interest || ''),
 '- message: ' + (lead.message || '')
].join('\n');
const body = { model: 'claude-haiku-4-5-20251001', max_tokens: 80, system, messages: [{ role: 'user', content: user }] };
return [{ json: { anthropic_body: body } }];

const lead = $('Compute Dedup Key').item.json;

function extractJson(text) {
  let t = (text || '').toString().trim();
  const m = t.match(/\{[\s\S]*\}/);
  if (m) t = m[0];
  return JSON.parse(t);
}

const gcc = ['AE','SA','QA','KW','BH','OM','EG'];
let language = gcc.includes(lead.country_code) ? 'ar' : 'en';
let langSource = 'heuristic';
try {
  const r = $('Detect Language (Haiku)').item.json;
  if (r && !r.error && Array.isArray(r.content) && r.content[0] && r.content[0].text) {
    const p = extractJson(r.content[0].text);
    if (['ar','en','fr','mixed'].includes(p.language)) { language = p.language; langSource = 'ai'; }
  }
} catch (e) {}

let intent = 'medium';
let intentDegraded = true;
try {
  const r = $('Classify Intent (Haiku)').item.json;
  if (r && !r.error && Array.isArray(r.content) && r.content[0] && r.content[0].text) {
    const p = extractJson(r.content[0].text);
    if (['high','medium','low','junk'].includes(p.intent)) { intent = p.intent; intentDegraded = false; }
  }
} catch (e) {}

const row = {
  source: lead.source || null,
  source_id: lead.source_id || null,
  first_name: lead.first_name || null,
  last_name: lead.last_name || null,
  phone: lead.phone || null,
  email: lead.email || null,
  property_interest: lead.property_interest || null,
  area_of_interest: lead.area_of_interest || null,
  language,
  country_code: lead.country_code || null,
  intent_classification: intent,
  dedup_key: lead.dedup_key,
  status: 'new'
};
return [{ json: { row, _language_source: langSource, _intent_degraded: intentDegraded } }];

const lead = $('Compute Dedup Key').item.json;

let sw = null;
try {
  const arr = ($json && $json.body) ? $json.body : (Array.isArray($json) ? $json : null);
  if (Array.isArray(arr) && arr[0]) sw = arr[0];
} catch (e) {}

const DEFAULT = { country_code: 'AE', timezone: 'Asia/Dubai', weekend_days: [5,6], quiet_hours_start: '22:00:00', quiet_hours_end: '08:00:00', respect_prayer_times: true };
const cfg = sw || DEFAULT;
const cc = cfg.country_code || 'AE';

const PRAYER = {
  AE:{city:'Dubai',country:'United Arab Emirates',method:16},
  SA:{city:'Riyadh',country:'Saudi Arabia',method:4},
  QA:{city:'Doha',country:'Qatar',method:10},
  KW:{city:'Kuwait City',country:'Kuwait',method:9},
  BH:{city:'Manama',country:'Bahrain',method:8},
  OM:{city:'Muscat',country:'Oman',method:4},
  EG:{city:'Cairo',country:'Egypt',method:5},
  JO:{city:'Amman',country:'Jordan',method:23},
  LB:{city:'Beirut',country:'Lebanon',method:2},
  MA:{city:'Casablanca',country:'Morocco',method:21}
};
const prayer = PRAYER[cc] || PRAYER.AE;
const tz = cfg.timezone || 'Asia/Dubai';
const now = DateTime.now().setZone(tz);

const weekendDays = Array.isArray(cfg.weekend_days) ? cfg.weekend_days : [5,6];
const dow = now.weekday % 7; // Luxon Mon=1..Sun=7 -> JS Sun=0..Sat=6
const isWeekend = weekendDays.includes(dow);

function hm(t){ const p = (t || '00:00').toString().split(':'); return { h: parseInt(p[0]||'0',10), m: parseInt(p[1]||'0',10) }; }
const qs = hm(cfg.quiet_hours_start);
const qe = hm(cfg.quiet_hours_end);
const sMin = qs.h*60 + qs.m;
const eMin = qe.h*60 + qe.m;
const nMin = now.hour*60 + now.minute;
let inQuiet;
if (sMin > eMin) inQuiet = (nMin >= sMin || nMin < eMin);
else inQuiet = (nMin >= sMin && nMin < eMin);

function nextOpen(d){
  let cand = d.set({ hour: qe.h, minute: qe.m, second: 0, millisecond: 0 });
  if (d > cand) cand = cand.plus({ days: 1 });
  let guard = 0;
  while (weekendDays.includes(cand.weekday % 7) && guard < 9){
    cand = cand.plus({ days: 1 }).set({ hour: qe.h, minute: qe.m, second: 0, millisecond: 0 });
    guard++;
  }
  return cand;
}

const resume = (!isWeekend && !inQuiet) ? now : nextOpen(now);

let wa = (lead.phone || '').toString().replace(/[^\d+]/g, '');
if (wa && wa[0] !== '+') wa = '+' + wa;

return [{ json: {
  whatsapp_number: wa,
  timezone: tz,
  country_code: cc,
  respect_prayer_times: cfg.respect_prayer_times !== false,
  prayer_city: prayer.city,
  prayer_country: prayer.country,
  prayer_method: prayer.method,
  is_weekend: isWeekend,
  in_quiet_hours: inQuiet,
  send_window_delayed: resume.toMillis() > now.toMillis() + 1000,
  send_window_resume: resume.toISO(),
  now_local: now.toISO()
} }];

const ctx = $('Resolve Send Context').item.json;
const now = DateTime.now().setZone(ctx.timezone);
let prayerCheck = 'ok';
let delayed = false;
let resume = now;

if (ctx.respect_prayer_times === false) {
  prayerCheck = 'skipped_country';
} else {
  let timings = null;
  try {
    const data = ($json && $json.body) ? $json.body : $json;
    if (data && data.data && data.data.timings) timings = data.data.timings;
  } catch (e) {}
  if (!timings) {
    prayerCheck = 'unavailable';
  } else {
    const names = ['Fajr','Dhuhr','Asr','Maghrib','Isha'];
    for (const n of names) {
      const t = timings[n];
      if (!t) continue;
      const parts = t.toString().slice(0,5).split(':');
      const pt = now.set({ hour: parseInt(parts[0],10), minute: parseInt(parts[1],10), second: 0, millisecond: 0 });
      if (Math.abs(now.diff(pt, 'minutes').minutes) <= 15) { delayed = true; break; }
    }
    if (delayed) { resume = now.plus({ minutes: 30 }); prayerCheck = 'delayed'; }
  }
}

return [{ json: {
  prayer_check: prayerCheck,
  prayer_delayed: delayed,
  prayer_resume: resume.toISO()
} }];

const lead = $('Compute Dedup Key').item.json;
const row = $('Assemble Lead Row').item.json.row;
const language = row.language || 'en';

const system = [
 'You write the FIRST WhatsApp message a MENA real-estate agency sends to a new lead, within seconds of their enquiry. It must feel like a real, attentive human agent, not a bot and not a marketing blast.',
 'Write ONE message, in the language given (ar | en | fr | mixed). For mixed, lead in Arabic. Match the country natural dialect register.',
 'The message MUST: (1) greet by first name if provided; (2) acknowledge their SPECIFIC stated interest (property type / area / buy or sell) so it is clearly personal; (3) end with EXACTLY ONE clear qualifying question (budget, and ask which currency, never assume; or timeline; or area; or buyer vs seller).',
 'Cultural rules (non-negotiable): formality by tone. A short casual or emoji enquiry uses informal Arabic anta (أنت); a formal, business, or older tone uses respectful hadretak (حضرتك); when unsure lean respectful. NEVER use in-sha-Allah (إن شاء الله) for logistics or timing, use we will do our best (سنبذل قصارى جهدنا). No religious greeting that assumes a religion, use neutral marhaba / Hello / Bonjour. Currency is never assumed.',
 'Style: under 500 characters, WhatsApp not email, no signature block, at most one tasteful emoji and only if it fits the lead tone (default none), no dream-home hype. Output ONLY the message text: no quotes, no JSON, no code fences.'
].join('\n');

const user = [
 'Lead:',
 '- first_name: ' + (lead.first_name || ''),
 '- language: ' + language,
 '- country: ' + (row.country_code || ''),
 '- buyer_or_seller: ' + (lead.buyer_or_seller || ''),
 '- property_interest: ' + (lead.property_interest || ''),
 '- area_of_interest: ' + (lead.area_of_interest || ''),
 '- their message (if any): ' + (lead.message || ''),
 '',
 'Write the acknowledgment message now.'
].join('\n');

const body = { model: 'claude-sonnet-5', max_tokens: 400, thinking: { type: 'disabled' }, system, messages: [{ role: 'user', content: user }] };
return [{ json: { anthropic_body: body, _language: language } }];

const language = $('Build Acknowledgment Request').item.json._language || 'en';
const lead = $('Compute Dedup Key').item.json;
const name = (lead.first_name || '').toString().trim();

const templates = {
  ar: (name ? ('مرحباً ' + name + '، ') : 'مرحباً، ') + 'شكراً لتواصلك معنا. يسعدنا مساعدتك في طلبك العقاري. ما المنطقة والميزانية التي تفكر بها، ومع تحديد العملة؟',
  fr: (name ? ('Bonjour ' + name + ', ') : 'Bonjour, ') + 'merci pour votre message. Avec plaisir pour vous aider dans votre recherche immobilière. Quel quartier et quel budget avez-vous en tête, et dans quelle devise ?',
  en: (name ? ('Hi ' + name + ', ') : 'Hello, ') + 'thanks for reaching out. Happy to help with your property search. Which area and budget do you have in mind, and in which currency?'
};

let text = '';
let degraded = true;
try {
  const data = ($json && $json.body) ? $json.body : $json;
  if (data && Array.isArray(data.content)) {
    const tb = data.content.find(function(b){ return b && b.type === 'text' && b.text; });
    if (tb) { text = tb.text.toString().trim(); if (text) degraded = false; }
  }
} catch (e) {}

if (!text) text = templates[language] || templates.en;
if (text.length > 500) text = text.slice(0, 497) + '…';

return [{ json: { ack_message: text, ack_degraded: degraded, language: language } }];
